errors=[]; texts=[]; differences=[]; bindings=[]
def diff(before,after,where=''):
    if isinstance(before,dict) and isinstance(after,dict):
        for key in sorted(set(before)|set(after)):
            if key not in before or key not in after:
                differences.append({'path':where+'/'+key,'before':before.get(key),'after':after.get(key)})
            else:
                diff(before[key],after[key],where+'/'+key)
    elif isinstance(before,list) and isinstance(after,list) and len(before)==len(after):
        for i,(a,b) in enumerate(zip(before,after)):
            diff(a,b,where+'/'+str(i))
    elif before!=after:
        differences.append({'path':where,'before':before,'after':after})
diff(initial_lesson,lesson,'/lesson')
diff(initial_exercises,exercises,'/exercises')
for change in differences:
